      "id": "r2",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "भोगा न भुक्ता वयमेव भुक्ता-",
          "end": "line"
        },
        {
          "n": 2,
          "text": "स्तपो न तप्तं वयमेव तप्ताः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "कालो न यातो वयमेव याता-",
          "end": "line"
        },
        {
          "n": 4,
          "text": "स्तृष्णा न जीर्णा वयमेव जीर्णाः ॥ १२ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "क्षान्तं न क्षमया गृहोचितसुखं त्यक्तं न संतोषतः",
          "end": "line"
        },
        {
          "n": 2,
          "text": "सोढा दुःसहशीतवाततपनाः क्लेशान्न तप्तं तपः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "ध्यातं वित्तमहर्निशं नियमितप्राणैर्न शम्भोः पदं",
          "end": "line"
        },
        {
          "n": 4,
          "text": "तत्तत्कर्म कृतं यदेव मुनिभिस्तैस्तैः फलैर्वञ्चिताः ॥ १३ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "बलिभिर्मुखमाक्रान्तं पलितैरङ्कितं शिरः ।",
          "end": "line"
        },
        {
          "n": 2,
          "text": "गात्राणि शिथिलायन्ते तृष्णैका तरुणायते ॥ १४ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "येनैवाम्बरखण्डेन संवीतो निशि चन्द्रमाः ।",
          "end": "line"
        },
        {
          "n": 2,
          "text": "तेनैव च दिवा भानुरहो दौर्गत्यमेतयोः ॥ १५ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "अवश्यं यातारश्चिरतरमुषित्वापि विषया",
          "end": "line"
        },
        {
          "n": 2,
          "text": "वियोगे को भेदस्त्यजति न जनो यत्स्वयममून् ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "व्रजन्तः स्वातन्त्र्यादतुलपरितापाय मनसः",
          "end": "line"
        },
        {
          "n": 4,
          "text": "स्वयं त्यक्ता ह्येते शमसुखमनन्तं विदधति ॥ १६ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
